def can_form_word(tiles: str, word: str) -> bool:
    """Check if a given word can be formed using the given tiles."

    # Create a dictionary to store the count of each tile
    tile_count = {}
    for tile in tiles:
        if tile in tile_count:
            tile_count[tile] += 1
        else:
            tile_count[tile] = 1

    # Check if the word can be formed using the tiles
    for letter in word:
        if letter not in tile_count or tile_count[letter] == 0:
            return False
        tile_count[letter] -= 1

    return True

