def min_time(tasks, n):
    if not tasks:
        return 0

    tasks = sorted(tasks, reverse=True)
    time = 0
    cooldown = [0] * len(tasks)

    for i in range(len(tasks)):
        while cooldown[tasks[i]-1] > 0:
            cooldown[tasks[i]-1] -= 1
            time += 1
        cooldown[tasks[i]-1] = n
        time += 1

    return time

