def longestSubstringWithSameLetters(s, k):
    n = len(s)
    max_length = 0
    for i in range(n):
        char_count = [0] * 26
        for j in range(i, n):
            char_count[ord(s[j]) - ord('a')] += 1
            if char_count[ord(s[j]) - ord('a')] == k:
                max_length = max(max_length, j - i + 1)
            elif char_count[ord(s[j]) - ord('a')] > k:
                break
    return max_length

