def floyd_warshall(adjacency_matrix):
    n = len(adjacency_matrix)
    # Create a copy of the original adjacency matrix to avoid modifying the input data
    shortest_paths = [[float('inf')] * n for _ in range(n)]

    # Initialize the shortest paths matrix with the original adjacency matrix
    for i in range(n):
        for j in range(n):
            shortest_paths[i][j] = adjacency_matrix[i][j]

    # Apply the Floyd-Warshall algorithm to find the shortest path distances between every pair of nodes
    for k in range(n):
        for i in range(n):
            for j in range(n):
                shortest_paths[i][j] = min(shortest_paths[i][j], shortest_paths[i][k] + shortest_paths[k][j])

