def can_form_palindrome(s: str) -> bool:
    # Convert the string to lower case and filter out non-alphanumeric characters
    s = ''.join(filter(str.isalnum, s)).lower()

    # Create a dictionary to store the frequency of each character
    char_freq = {}

    # Count the frequency of each character
    for char in s:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # A string can be rearranged to form a palindrome if and only if at most one character has an odd frequency
    odd_count = 0
    for freq in char_freq.values():
        if freq % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False

    return True

