def find_words(s, d):
    def backtrack(s, word, path):
        if word == s: return [path + [word]]
        if not s: return []
        res = []
        for i in range(1, len(s) + 1):
            if s[:i] in d:
                res.extend(backtrack(s[i:], word + s[:i], path + [word + s[:i]]))
        return res

    return [item for sublist in [backtrack(s, '', []) for s in d] for item in sublist]}

